// Generated by aurora@aurora-smart-home (home-assistant skill)
// https://github.com/tonylofgren/aurora-smart-home
//
// cost-title.ts — OpenCode V2 server plugin (verified against v2.0.16).
// Appends " · $1.23 · 45k tok" to the session title after each finished turn,
// so the running cost is always visible in OpenChamber (VS Code panel, web, desktop).
//
// Everything below was checked against the installed opencode v2.0.16
// (@opencode/schema@2.0.16 + @opencode/client@2.0.16 + the running server's
// OpenAPI spec), not just the latest docs:
//
//   - session.usage.updated  (ephemeral)
//       data: { sessionID, cost, tokens: { input, output, reasoning, cache: { read, write } } }
//   - session.execution.succeeded / .failed / .interrupted  (durable)
//       data: { sessionID, ... }   ← all three end a turn, and cost was spent on all three
//   - session.renamed  (durable)
//       data: { sessionID, title } ← catches the auto-title that lands *after* the
//                                    first turn finished, plus manual renames
//   - session.deleted  (durable)   data: { sessionID } ← prune the usage cache
//
//   - Title is persisted with ctx.session.update({ sessionID, title }) — the 2.0.16
//     "session.update" op (PATCH /api/session/{sessionID}, body { title }). Newer
//     releases rename that op to session.rename; we prefer rename when it exists.
//   - 2.0.16 auto-discovers direct .ts/.js plugin files in BOTH .opencode/plugin/
//     (the V1-compat dir this file lives in) and .opencode/plugins/.
//
// Session scoping: the event stream is server-global (every project on this
// machine), so renames are restricted to sessions belonging to the project this
// plugin instance was loaded for.
//
// Set COST_TITLE_DEBUG=1 in the server process env to log every event type the
// plugin sees. Set COST_TITLE_WARN_USD=5 to prefix ⚠ on sessions costing $5+.

// NOTE: no `import { Plugin } from "@opencode/plugin"` here. The 2.0.16 server
// plugin loader imports local plugin files with plain Bun resolution and cannot
// resolve the bare "@opencode/plugin" specifier (it is not registered as a
// virtual module server-side — only "@opencode/plugin/tui" is, for TUI plugins).
// Plugin.define() is an identity helper, so exporting the definition object
// directly is exactly equivalent and loads on 2.0.16.

const SUFFIX = /\s·\s\$\d+(\.\d+)?(\s·\s[\d.]+[kM]?\stok)?$/
const DEBUG = process.env.COST_TITLE_DEBUG === "1"
const WARN_AT = Number(process.env.COST_TITLE_WARN_USD ?? "0") // e.g. 5 → prefix ⚠ over $5

type Usage = { cost: number; tokens: number }

const fmtTokens = (n: number) =>
  n >= 1e6 ? (n / 1e6).toFixed(1) + "M" : n >= 1e3 ? Math.round(n / 1e3) + "k" : String(n)

const sumTokens = (t: any) =>
  Number(t?.input ?? 0) + Number(t?.output ?? 0) + Number(t?.reasoning ?? 0) +
  Number(t?.cache?.read ?? 0) + Number(t?.cache?.write ?? 0)

// Every event that ends a turn — cost was spent regardless of outcome.
const EXEC_DONE = new Set([
  "session.execution.succeeded",
  "session.execution.failed",
  "session.execution.interrupted",
])

export default {
  id: "local.cost-title",
  setup(ctx: any) {
    const usage = new Map<string, Usage>()
    const seen = new Set<string>()
    const ac = new AbortController()

    // Scope renames to this plugin instance's project.
    const ourProjectID: string | undefined = ctx.location?.project?.id
    const ourDirs: string[] = [ctx.location?.project?.canonical, ctx.location?.directory]
      .filter((d: unknown): d is string => typeof d === "string" && d.length > 0)

    const inScope = (s: any) => {
      if (ourProjectID) return s?.projectID === ourProjectID
      const dir = s?.location?.directory
      if (ourDirs.length === 0) return true // no location info available → don't filter
      return ourDirs.some((d) => dir === d || (typeof dir === "string" && dir.startsWith(d + "/")))
    }

    const setTitle = async (sessionID: string, title: string) => {
      // 2.0.16 persists titles via session.update (PATCH /api/session/{id});
      // newer releases expose session.rename. Prefer rename when present.
      if (typeof ctx.session.rename === "function") return ctx.session.rename({ sessionID, title })
      return ctx.session.update({ sessionID, title })
    }

    const getSession = async (sessionID: string) => {
      const r = await ctx.session.get({ sessionID })
      return r?.data ?? r // 2.0.16 returns SessionInfo directly; unwrap defensively
    }

    const applyTitle = async (sessionID: string, hintTitle?: string) => {
      const s = await getSession(sessionID)
      if (!s || s.parentID) return // label root sessions only
      if (!inScope(s)) return

      // Prefer the persisted session totals; fall back to the last usage event.
      const cost = Number(s.cost ?? usage.get(sessionID)?.cost ?? 0)
      const tokens = s.tokens ? sumTokens(s.tokens) : (usage.get(sessionID)?.tokens ?? 0)

      const current = String(hintTitle ?? s.title ?? "").trim()
      const base = current.replace(/^⚠\s/, "").replace(SUFFIX, "").trim()
      if (!base || /^New session/i.test(base)) return // let auto-title land first

      const warn = WARN_AT > 0 && cost >= WARN_AT ? "⚠ " : ""
      const title = `${warn}${base} · $${cost.toFixed(2)} · ${fmtTokens(tokens)} tok`
      // Idempotent: our own rename re-fires session.renamed, but the re-computed
      // title equals the current one, so the loop settles immediately.
      if (title !== current) await setTitle(sessionID, title)
    }

    ;(async () => {
      for await (const e of ctx.event.subscribe({ signal: ac.signal })) {
        try {
          const type: string = e?.type
          const d: any = e?.data ?? e?.properties ?? {}
          if (DEBUG && !seen.has(type)) {
            seen.add(type)
            console.log("[cost-title] event", type, Object.keys(d))
          }

          if (type === "session.usage.updated" && d.sessionID) {
            usage.set(d.sessionID, { cost: Number(d.cost ?? 0), tokens: sumTokens(d.tokens) })
            continue
          }

          if (type === "session.deleted" && d.sessionID) {
            usage.delete(d.sessionID)
            continue
          }

          if (!d.sessionID) continue

          if (EXEC_DONE.has(type)) {
            await applyTitle(d.sessionID)
          } else if (type === "session.renamed") {
            // The auto-generated title (or a manual rename) can land after the
            // turn already finished — re-apply the suffix on top of it.
            await applyTitle(d.sessionID, typeof d.title === "string" ? d.title : undefined)
          }
        } catch (err) {
          if (DEBUG) console.error("[cost-title]", err)
        }
      }
    })().catch((err) => {
      if (DEBUG && !ac.signal.aborted) console.error("[cost-title] stream ended", err)
    })

    console.log(
      `[cost-title] loaded (opencode ${ctx.app?.version ?? "?"}, project ${ourProjectID ?? ourDirs[0] ?? "unknown"})`,
    )

    return () => ac.abort()
  },
}
